from random import Random

def normalize_name(value):
    return value.strip()

def test_normalize_is_idempotent():
    samples = [' Ana ', 'loops', '  spaced  words  ', '']
    for value in samples:
        once = normalize_name(value)
        twice = normalize_name(once)
        assert twice == once

def test_sorted_preserves_items():
    rng = Random(7)
    for _ in range(20):
        values = [rng.randrange(10) for _ in range(8)]
        result = sorted(values)
        assert sorted(result) == sorted(values)
        assert all(result[i] <= result[i + 1] for i in range(len(result) - 1))

test_normalize_is_idempotent()
test_sorted_preserves_items()
print('two properties checked')

