def normalize_tag(value):
    return value.strip().lower()

samples = [' Python ', 'DATA', '  spaced tag  ', '']
for sample in samples:
    once = normalize_tag(sample)
    assert normalize_tag(once) == once

assert normalize_tag(' Python ') == 'python'
